const input = $input.first()?.json;
if (!input) return [];
const rows = Array.isArray(input) ? input : Array.isArray(input.body) ? input.body : input.id ? [input] : [];
return rows
  .filter((record) => record?.status === 'processing' && record.job_type === 'parse_document' && record.claim_token)
  .map((record) => ({ json: { job_id: record.id, claim_token: record.claim_token, project_id: record.project_id, document_id: record.document_id, job_type: record.job_type, status: record.status, metadata: record.metadata ?? {}, valid: Boolean(record.id && record.claim_token && record.project_id && record.document_id) } }));

const raw = $input.first().json;
const document = Array.isArray(raw) ? raw[0] : raw;
const job = $node['Normalize Job Payload'].json;

if (!document?.id) {
  throw new Error('Document row was not found for queued AI job.');
}

return [
  {
    json: {
      job_id: job.job_id,
      claim_token: job.claim_token,
      project_id: job.project_id,
      document_id: job.document_id,
      document,
      worker_request: {
        job_id: job.job_id,
        claim_token: job.claim_token,
        project_id: job.project_id,
        document_id: job.document_id,
        storage_bucket: document.storage_bucket || 'project-evidence',
        storage_path: document.storage_path,
        title: document.title,
        file_name: document.file_name,
        document_type: document.document_type,
        document_date: document.document_date
      }
    }
  }
];

const result = $input.first().json;
const { job_id, claim_token, project_id, document_id, document } = $node['Build Worker Request'].json;

// Citation validation mirrors the source-integrity contract: every fact and
// summary source must quote an exact substring of the chunk it cites, with an
// in-range confidence. The worker owns chunk persistence; this node publishes
// only the validated final rows through the fenced RPC.
const chunks = (result.chunks ?? []).map((chunk, index) => ({
  chunk_index: Number.isInteger(chunk.chunk_index) ? chunk.chunk_index : index,
  chunk_text: String(chunk.chunk_text ?? chunk.text ?? '').trim()
}));
const chunksByIndex = new Map(chunks.map((chunk) => [chunk.chunk_index, chunk]));
const requireSource = (index, excerpt, label) => {
  const chunk = chunksByIndex.get(index);
  if (!chunk || typeof excerpt !== 'string' || !excerpt || !chunk.chunk_text.includes(excerpt)) {
    throw new Error('The document worker returned an invalid ' + label + ' citation.');
  }
};

const facts = (result.facts ?? []).map((fact) => {
  requireSource(fact.evidence_chunk_index, fact.excerpt ?? fact.evidence_excerpt, 'fact');
  if (typeof fact.confidence !== 'number' || !Number.isFinite(fact.confidence) || fact.confidence < 0 || fact.confidence > 1) {
    throw new Error('The document worker returned invalid fact confidence.');
  }
  if (!['risk', 'issue', 'milestone', 'decision', 'owner_action'].includes(fact.fact_type) || typeof fact.extracted_text !== 'string' || !fact.extracted_text.trim() || typeof fact.original_value !== 'string') {
    throw new Error('The document worker returned an invalid fact.');
  }
  return {
    fact_type: fact.fact_type,
    extracted_text: fact.extracted_text.trim(),
    original_value: fact.original_value.trim(),
    confidence: fact.confidence,
    evidence_excerpt: fact.excerpt ?? fact.evidence_excerpt,
    evidence_chunk_index: fact.evidence_chunk_index
  };
});

// A completed result must carry a fully verified summary; an explicit
// needs_review result may legitimately arrive without one (guardrail
// fallback). In that case publish the validated facts/alerts/actions and let
// the document land as needs_review — never invent a citation or treat
// fallback text as a factual summary.
const isReviewFallback = result.processing_status === 'needs_review';
let summary = null;
let verifiedSummarySources = [];
if (result.summary?.summary_text) {
  if (typeof result.summary.summary_text !== 'string' || !result.summary.summary_text.trim() || typeof result.summary.confidence !== 'number' || !Number.isFinite(result.summary.confidence) || result.summary.confidence < 0 || result.summary.confidence > 1) {
    throw new Error('The document worker returned an invalid summary.');
  }
  verifiedSummarySources = result.summary_sources ?? [];
  if (!verifiedSummarySources.length) {
    // A needs_review fallback whose summary carries no verified source is
    // warning text, not a factual summary: drop it and let processing_error
    // carry the warning. Facts, alerts, and actions that validated remain.
    // Only the dropped fallback lands here; a sourced summary always publishes.
    if (!isReviewFallback) throw new Error('The document summary has no verified source citations.');
    summary = null;
    verifiedSummarySources = [];
  } else {
    for (const source of verifiedSummarySources) {
      requireSource(source.evidence_chunk_index, source.excerpt, 'summary');
      if (typeof source.confidence !== 'number' || !Number.isFinite(source.confidence) || source.confidence < 0 || source.confidence > 1) {
        throw new Error('The document worker returned invalid summary confidence.');
      }
    }
    summary = {
      summary_text: result.summary.summary_text.trim(),
      confidence: result.summary.confidence,
      quality_warning: result.summary.quality_warning ?? null,
      metadata: { generated_by: 'n8n_document_worker', job_id, document_title: document.title }
    };
  }
} else if (!isReviewFallback) {
  throw new Error('The document worker returned an invalid summary.');
}

const health_snapshots = (result.health_snapshots ?? [])
  .filter((snapshot) => snapshot.snapshot_date !== null && snapshot.snapshot_date !== undefined)
  .map((snapshot) => {
    if (typeof snapshot.snapshot_date !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(snapshot.snapshot_date)) {
      throw new Error('The document worker returned an invalid evidenced health snapshot date.');
    }
    return {
      dimension: snapshot.dimension,
      score: snapshot.score,
      status: snapshot.status,
      evidence_coverage: snapshot.evidence_coverage,
      status_text: snapshot.status_text,
      snapshot_date: snapshot.snapshot_date,
      source_summary: snapshot.source_summary
    };
  });

const alerts = (result.alerts ?? []).map((alert) => ({
  severity: alert.severity,
  impacted_area: alert.impacted_area,
  explanation: alert.explanation,
  evidence_count: alert.evidence_count,
  recommended_action: alert.recommended_action,
  source_path: alert.source_path ?? null
}));
const actions = (result.actions ?? []).map((action) => ({
  title: action.title,
  owner_name: action.owner_name,
  due_date: action.due_date ?? null,
  priority: action.priority,
  status: action.status,
  source_path: action.source_path ?? null
}));
const anomalies = (result.anomalies ?? []).map((anomaly) => ({
  category: anomaly.category,
  missing_field: anomaly.missing_field ?? null,
  severity: anomaly.severity,
  status: anomaly.status ?? 'open',
  title: anomaly.title,
  affected_item: anomaly.affected_item,
  explanation: anomaly.explanation,
  impact: anomaly.impact,
  impact_rating: anomaly.impact_rating,
  recommended_action: anomaly.recommended_action,
  suggested_owners: anomaly.suggested_owners,
  evidence_count: anomaly.evidence_count,
  absence_type: anomaly.absence_type,
  rationale: anomaly.rationale,
  source_path: anomaly.source_path ?? null
}));

return [{ json: {
  p_job_id: job_id,
  p_claim_token: claim_token,
  p_result: {
    worker: result.worker ?? 'next_document_worker',
    processing_status: result.processing_status === 'needs_review' ? 'needs_review' : 'completed',
    processing_error: result.processing_error ?? null,
    facts,
    summary,
    summary_sources: verifiedSummarySources.map((source) => ({
      chunk_index: source.evidence_chunk_index,
      excerpt: source.excerpt,
      confidence: source.confidence
    })),
    health_snapshots,
    alerts,
    actions,
    anomalies,
    extraction_run_metadata: { parser_metadata: result.parser_metadata ?? {}, chunk_count: chunks.length }
  }
} }];
